Sélecteurs.exemple:
/* seulement les <p class="note"> */
p.note {
  color: gray;
}

Propriétés de mise en forme du texte.exemple:
p {
  font: italic bold 16px Arial, sans-serif;
}

h1 {
  text-align: center;
}
p {
  text-align: justify;
}

Propriétés des listes.exemple:
ul {
  list-style-type: square;
}
ol {
  list-style-type: upper-roman;
}

Propriétés d'arrière-plan.exemple:
body {
  background-image: url("images/logo.png");
  background-repeat: repeat-y;
  background-position: center;
}

Propriétés des images.exemple:
img.archive {
  filter: grayscale(100%);
}
img.flou {
  filter: blur(3px);
}

Propriétés des tableaux.exemple:
table {
  border-collapse: collapse;
}
td, th {
  border: 1px solid #0D2B6B;
}

Propriétés des boîtes.exemple:
.bandeau {
  position: fixed;
  top: 0px;
  width: 100%;
}
.badge {
  position: absolute;
  top: 10px;
  right: 10px;
}

nav {
  float: left;
  width: 25%;
}
section {
  float: right;
  width: 70%;
}

.carte {
  padding: 15px;            /* 4 côtés */
  padding: 10px 20px;       /* haut-bas  gauche-droite */
  padding: 5px 10px 15px 20px; /* haut droite bas gauche */
}

section {
  margin: 20px;
}
.centre {
  width: 800px;
  margin: 0px auto;   /* centrage horizontal */
}

Animation.exemple:
.bateau {
  animation-name: traversee;
  animation-duration: 3s;
  animation-iteration-count: infinite;
  animation-direction: alternate;
}

@keyframes traversee {
  0%   { left: 0px; }
  100% { left: 300px; }
}
.bateau {
  position: relative;
  animation: traversee 3s 0s infinite alternate;
}
